def transform(grid):
    output = []
    for row in grid:
        new_row = []
        for col_idx, val in enumerate(row):
            # Identify the two values: background (majority) and special (minority)
            if val == 4:  # Background value
                # Rightmost 4 columns preserved, rest become 3
                if col_idx >= 21:
                    new_row.append(4)
                else:
                    new_row.append(3)
            else:  # Special value (8)
                new_row.append(8)
        output.append(new_row)
    return output
